import{_ as o,o as t,c as d,a3 as s}from"./chunks/framework.DEy3KOfk.js";const h=JSON.parse('{"title":"Building","description":"","frontmatter":{"navigation":{"category":"Plugin development"},"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/docs/building.md"},"headers":[],"relativePath":"guides/building.md","filePath":"docs/building.md","lastUpdated":1791428287000}'),i={name:"guides/building.md"};function a(n,e,c,r,l,p){return t(),d("div",null,[...e[0]||(e[0]=[s('<h1 id="building" tabindex="-1">Building <a class="header-anchor" href="#building" aria-label="Permalink to &quot;Building&quot;">​</a></h1><h2 id="the-build-tool" tabindex="-1">The build tool <a class="header-anchor" href="#the-build-tool" aria-label="Permalink to &quot;The build tool&quot;">​</a></h2><p><code>pumpkin-plugins-build</code> (<code>tools/build</code>) turns a plugin into a <code>.wasm</code> component. It is configured by the <code>pumpkinPlugin</code> key in each plugin&#39;s <code>package.json</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pumpkinPlugin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;entry&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;src/plugin.ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;output&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;build/my-plugin.wasm&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;wasi&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [] }</span></span></code></pre></div><p>It uses the WIT from the pinned <code>@pumpkinmc/pumpkin-api-ts</code> (the version is the <code>catalog:</code> entry in <code>pnpm-workspace.yaml</code>, and it must match the Pumpkin server&#39;s plugin ABI), esbuild and the Wasmtime 48 CLI fork of <code>componentize-qjs</code>. The fork is needed because the upstream Wasmtime 47 CLI fails to link the WASI HTTP types used by plugins. The pinned release&#39;s own build script uses a componentizer that produces 55 MB plugins and can&#39;t run the WASI socket code.</p><table tabindex="0"><thead><tr><th>Command</th><th>Result</th></tr></thead><tbody><tr><td><code>pumpkin-plugins-build</code></td><td><code>build/&lt;plugin&gt;.wasm</code>, with the WIT it was built from in <code>build/wit/</code> (a copy, since the WASI imports are added)</td></tr><tr><td><code>pumpkin-plugins-build --types-only</code></td><td>Guest types in <code>build/types/</code> for <code>tsc</code> and your editor</td></tr></tbody></table><p>Types go to a separate directory so <code>build</code> and <code>typecheck</code> can run in parallel without touching the same files. Run <code>pnpm typecheck</code> once after a fresh checkout so your editor finds the types. The shared <code>plugin-kit</code> package does the same for its own source, generating declarations for its filesystem imports in its ignored <code>build/types/</code> directory.</p><p><code>PUMPKIN_API_DIR</code> points the tool at a different <code>pumpkin-api-ts</code> checkout.</p><p>A plugin is built against the API&#39;s WIT as <code>pumpkin-api-ts</code> ships it, plus the WASI imports it asks for.</p><p><code>pumpkin-api-ts</code> ships its own declarations for <code>pumpkin:plugin/*</code>, and TypeScript keeps the first declaration of a module it sees. So a plugin&#39;s <code>tsconfig.json</code> lists the generated <code>build/types/bindings/**/*.d.ts</code> before <code>src</code> in <code>include</code> (the generator&#39;s template does), which makes the generated declarations win (they use <code>number</code> for 64-bit values).</p><h2 id="runtime-caveats" tabindex="-1">Runtime caveats <a class="header-anchor" href="#runtime-caveats" aria-label="Permalink to &quot;Runtime caveats&quot;">​</a></h2><p>Plugins run on QuickJS inside the server&#39;s WebAssembly runtime:</p><ul><li>There is no global <code>TextEncoder</code>, <code>TextDecoder</code> or <code>fetch</code>. <code>fflate</code> provides <code>strToU8</code> and <code>strFromU8</code>. Plugins that need HTTP can import <code>wasi:http</code> by declaring the <code>http</code> capability; the update-check tool already does this.</li><li><code>u64</code>/<code>s64</code> values are plain JS numbers in both directions. Passing a <code>BigInt</code> panics the guest, so the build rewrites the generated types from <code>bigint</code> to <code>number</code>.</li><li>The base <code>Plugin</code> class&#39;s <code>scheduleDelayedTask</code> and <code>scheduleRepeatingTask</code> pass <code>BigInt</code>, so they panic. Call <code>pumpkin:plugin/scheduler</code> directly with numbers and export your own <code>handleTask</code> that handles your task ids and falls back to the API&#39;s. A local export takes precedence over <code>export *</code>.</li><li>Plugins that request permissions are prompted for on the server console the first time they load. Hot reload can&#39;t prompt and denies them, so the first load needs a restart.</li><li>Two builds of identical source produce different bytes. Anything that signs or uploads a build must use the artifact from the build job, never a rebuild.</li></ul><h2 id="turborepo" tabindex="-1">Turborepo <a class="header-anchor" href="#turborepo" aria-label="Permalink to &quot;Turborepo&quot;">​</a></h2><p>Tasks are defined in <code>turbo.json</code> and run with the root scripts (<code>pnpm build</code>, <code>pnpm typecheck</code>, <code>pnpm test</code>, <code>pnpm test:integration</code>, <code>pnpm readme</code>, <code>pnpm package</code>):</p><table tabindex="0"><thead><tr><th>Task</th><th>Notes</th></tr></thead><tbody><tr><td><code>transit</code></td><td>Does nothing; it carries a package&#39;s dependencies&#39; hashes (see below)</td></tr><tr><td><code>build</code></td><td>Caches <code>build/**</code> except <code>build/types/**</code></td></tr><tr><td><code>typecheck</code></td><td>Caches the generated <code>build/types/**</code>, so a cache hit restores them</td></tr><tr><td><code>test</code></td><td>Cached on inputs only</td></tr><tr><td><code>test:integration</code></td><td>Depends on <code>build</code>, never cached (it starts a real server)</td></tr><tr><td><code>readme</code>, <code>readme:check</code></td><td>Never cached, they write or inspect files</td></tr></tbody></table><p>Run one plugin with <code>pnpm exec turbo run build --filter=@pumpkin-plugins/&lt;folder&gt;</code>.</p><h2 id="run-all-plugins-on-pumpkin" tabindex="-1">Run all plugins on Pumpkin <a class="header-anchor" href="#run-all-plugins-on-pumpkin" aria-label="Permalink to &quot;Run all plugins on Pumpkin&quot;">​</a></h2><p>Run <code>pnpm dev</code> to build every plugin and start the latest stable Pumpkin release. GitHub&#39;s latest release endpoint excludes prereleases, so the <code>nightly</code> build is not selected. Release metadata is cached in <code>.cache/pumpkin</code> for 24 hours, so repeated starts reuse it without another GitHub lookup. Set <code>PUMPKIN_REFRESH_RELEASE=1</code> to force a one-run refresh. The server binary is also cached there and checked against the release&#39;s <code>checksums.sha256</code>.</p><p>Run <code>pnpm dev:no-hot-reload</code> to build once and start the same server with plugin hot reload and build watchers disabled. Restart the command after changing a plugin.</p><p>The dev server lives in <code>.cache/pumpkin-dev</code>, so its world and settings remain between runs. Each command sets Pumpkin&#39;s plugin hot reload to match the selected mode. In hot-reload mode, <code>pnpm dev</code> uses <code>turbo watch</code> to rebuild plugins as workspace packages change and copies each completed <code>.wasm</code> into the server&#39;s <code>plugins/</code> directory. This copy is needed because Pumpkin watches that directory, while build outputs live under each package. A file linked to a build output would not notify Pumpkin when the target changes. Automatic Market update checks are disabled for these development builds. Reloading plugins that request permissions still requires granting permissions on their initial load.</p><p>Set <code>PUMPKIN_BIN</code> to use a local server binary instead of downloading the latest release. Set <code>PUMPKIN_CACHE_DIR</code> to change the binary cache directory. To reset the dev server&#39;s world, config and plugins, stop the server and remove <code>.cache/pumpkin-dev</code>.</p><p>The build tool and test harness <code>typecheck</code> tasks run <code>tsc --noEmit</code>, so their package-level Turbo configurations declare no outputs. Plugin typechecks keep the root <code>build/types/**</code> outputs because they generate guest declarations needed by builds and editors.</p><p>Things to know when changing <code>turbo.json</code>:</p><ul><li><strong>Cache invalidation.</strong> The workspace packages are used as source (their <code>exports</code> point at <code>src/</code>), so nothing is built in between and Turborepo has no reason to look at a dependency&#39;s files. The <code>transit</code> task is the fix from the Turborepo docs (&quot;transit nodes&quot;): it has no script and depends on <code>^transit</code>, and <code>build</code>, <code>typecheck</code> and <code>test</code> depend on it, so a change in any package a package depends on (including <code>devDependencies</code> such as <code>tools/build</code>, whose <code>wasi-wit.lock.json</code> and <code>src/</code> decide what a plugin is built from) invalidates exactly its dependents. New tools need nothing added, as long as a plugin lists them in its <code>package.json</code>. <code>globalDependencies</code> is only for inputs outside any package: <code>tsconfig.base.json</code> and <code>pnpm-workspace.yaml</code> (the API version). The lockfile and the root <code>package.json</code> invalidate everything, and so do the packages the root <code>package.json</code> depends on (<code>tools/docs</code> and <code>tools/signing</code>), because Turborepo treats those as global.</li><li><strong>Environment variables.</strong> Turborepo runs tasks in strict env mode, so a variable a task reads has to be declared, or it never reaches the task. <code>PUMPKIN_API_DIR</code> (another <code>pumpkin-api-ts</code> checkout) changes what <code>build</code> and <code>typecheck</code> produce, so it is in their <code>env</code> and part of their cache key. The <code>PUMPKIN_*</code> variables the test harness and the build&#39;s download cache read are in <code>globalPassThroughEnv</code>; they don&#39;t affect cache keys, which is fine because they only say where things are or what to run in uncached tasks. <code>TMPDIR</code> isn&#39;t passed through, so tests run under Turborepo create their temp directories in <code>/tmp</code>.</li><li><strong><code>^</code> dependencies need a task the root doesn&#39;t have.</strong> The root scripts share names with tasks (<code>&quot;build&quot;: &quot;turbo run build&quot;</code>), so <code>dependsOn: [&quot;^build&quot;]</code> would make the root package a dependency of itself and fail or loop. <code>transit</code> is not a root script, which is why it can use <code>^transit</code>. Don&#39;t add a root script of that name. See the Turborepo docs page &quot;Missing root task in turbo.json&quot;.</li><li><strong>Linting runs outside Turborepo.</strong> <code>pnpm lint</code> calls Biome and ESLint directly. Both are fast, so caching them wouldn&#39;t gain anything.</li><li><strong><code>agentGuidance</code> is off.</strong> By default Turborepo writes an <code>AGENTS.md</code> when it detects an AI agent and re-adds it if it is deleted. <code>&quot;agentGuidance&quot;: false</code> is the opt-out.</li><li><strong>Package manager.</strong> Declared with <code>devEngines.packageManager</code> in the root <code>package.json</code>, which Turborepo, pnpm and <code>pnpm/action-setup</code> all read.</li><li><strong>Remote cache</strong> isn&#39;t configured. CI caches <code>.turbo</code> with <code>actions/cache</code>. Set <code>TURBO_TOKEN</code> and <code>TURBO_TEAM</code> to use a remote cache instead.</li></ul><p>The installed Turborepo ships its own docs for the exact version: <code>docs/</code> inside the <code>turbo</code> package (<code>node -p &quot;require(&#39;path&#39;).dirname(require.resolve(&#39;turbo/package.json&#39;))&quot;</code> from the repo root).</p>',26)])])}const g=o(i,[["render",a]]);export{h as __pageData,g as default};
